/**
 * TypeScript mirrors of the FastAPI backend's Pydantic schemas
 * (see backend/schemas.py). Keep these in sync by hand — there's no
 * codegen step in a 12-hour hackathon build.
 */

export type TicketTag = "Frontend" | "Backend" | "Design" | "Infra";
export type TicketPriority = "High" | "Medium" | "Low";
export type InsightTrend = "up" | "down" | "flat";

export interface Ticket {
  id: string;
  title: string;
  tag: TicketTag;
  priority: TicketPriority;
  storyPoints: number;
  acceptanceCriteria: string[];
}

export interface VisualAssetPrompt {
  assetName: string;
  falPrompt: string;
}

export interface CalaDataInsight {
  id: string;
  question: string;
  metricTarget: string;
  value: string;
  trend: InsightTrend;
  summary: string;
}

export interface ProcessMeetingResponse {
  summary: string;
  tickets: Ticket[];
  visualAssets: VisualAssetPrompt[];
  dataInsights: CalaDataInsight[];
}

export interface GenerateAssetResponse {
  imageUrl: string;
}

export interface DataInsightsResponse {
  dataInsights: CalaDataInsight[];
}

/**
 * Thin client for PrismAI's FastAPI backend (see backend/main.py).
 * Base URL is configurable via NEXT_PUBLIC_API_BASE_URL (see .env.local.example),
 * defaulting to the local dev server started with:
 *   uvicorn main:app --reload --port 8000
 */

import type {
  DataInsightsResponse,
  GenerateAssetResponse,
  ProcessMeetingResponse,
} from "./types";

const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_BASE_URL?.replace(/\/+$/, "") ?? "http://localhost:8000";

export class ApiError extends Error {
  status?: number;

  constructor(message: string, status?: number) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

async function postJson<TResponse>(path: string, body: unknown): Promise<TResponse> {
  let response: Response;
  try {
    response = await fetch(`${API_BASE_URL}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
  } catch {
    throw new ApiError(
      `Could not reach the PrismAI backend at ${API_BASE_URL}. Is it running? ` +
        `(cd backend && uvicorn main:app --reload --port 8000)`
    );
  }

  if (!response.ok) {
    const detail = await response.json().catch(() => null);
    throw new ApiError(
      typeof detail?.detail === "string" ? detail.detail : `Request to ${path} failed (${response.status}).`,
      response.status
    );
  }

  return (await response.json()) as TResponse;
}

/** POST /api/process-meeting — backlog + moodboard prompts + data insights, in one shot. */
export function processMeeting(transcript: string): Promise<ProcessMeetingResponse> {
  return postJson<ProcessMeetingResponse>("/api/process-meeting", { transcript });
}

/** POST /api/generate-asset — renders a single moodboard prompt via Fal.ai Flux Schnell. */
export function generateAsset(prompt: string): Promise<GenerateAssetResponse> {
  return postJson<GenerateAssetResponse>("/api/generate-asset", { prompt });
}

/** POST /api/data-insights — re-query Cala for fresh analytics off the same transcript. */
export function fetchDataInsights(transcript: string): Promise<DataInsightsResponse> {
  return postJson<DataInsightsResponse>("/api/data-insights", { transcript });
}

import { ListChecks } from "lucide-react";
import { clsx } from "clsx";
import type { Ticket, TicketPriority, TicketTag } from "../lib/types";

const TAG_STYLES: Record<TicketTag, string> = {
  Frontend: "bg-blue-100 text-blue-700 dark:bg-blue-500/15 dark:text-blue-300",
  Backend: "bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300",
  Design: "bg-fuchsia-100 text-fuchsia-700 dark:bg-fuchsia-500/15 dark:text-fuchsia-300",
  Infra: "bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300",
};

const PRIORITY_STYLES: Record<TicketPriority, string> = {
  High: "bg-red-100 text-red-700 dark:bg-red-500/15 dark:text-red-300",
  Medium: "bg-amber-100 text-amber-700 dark:bg-amber-500/15 dark:text-amber-300",
  Low: "bg-zinc-100 text-zinc-600 dark:bg-zinc-500/15 dark:text-zinc-400",
};

function TicketCard({ ticket }: { ticket: Ticket }) {
  return (
    <li className="rounded-xl border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-zinc-950">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="text-xs font-mono text-zinc-400">{ticket.id}</p>
          <h3 className="mt-0.5 font-medium text-zinc-900 dark:text-zinc-50">{ticket.title}</h3>
        </div>
        <span className="shrink-0 rounded-full bg-violet-100 px-2 py-1 text-xs font-semibold text-violet-700 dark:bg-violet-500/15 dark:text-violet-300">
          {ticket.storyPoints} SP
        </span>
      </div>

      <div className="mt-3 flex flex-wrap gap-1.5">
        <span className={clsx("rounded-full px-2 py-0.5 text-xs font-medium", TAG_STYLES[ticket.tag])}>
          {ticket.tag}
        </span>
        <span className={clsx("rounded-full px-2 py-0.5 text-xs font-medium", PRIORITY_STYLES[ticket.priority])}>
          {ticket.priority}
        </span>
      </div>

      {ticket.acceptanceCriteria.length > 0 && (
        <ul className="mt-3 space-y-1 border-t border-zinc-100 pt-3 dark:border-zinc-800">
          {ticket.acceptanceCriteria.map((criterion, index) => (
            <li key={index} className="flex gap-2 text-xs text-zinc-600 dark:text-zinc-400">
              <span className="mt-1 size-1 shrink-0 rounded-full bg-zinc-300 dark:bg-zinc-600" />
              {criterion}
            </li>
          ))}
        </ul>
      )}
    </li>
  );
}

export function BacklogPanel({ tickets }: { tickets: Ticket[] }) {
  const totalPoints = tickets.reduce((sum, t) => sum + t.storyPoints, 0);

  return (
    <section className="flex h-full flex-col rounded-2xl border border-zinc-200 bg-zinc-50/60 dark:border-zinc-800 dark:bg-zinc-900/40">
      <header className="flex items-center justify-between border-b border-zinc-200 px-4 py-3 dark:border-zinc-800">
        <div className="flex items-center gap-2">
          <ListChecks className="size-4 text-violet-600 dark:text-violet-400" />
          <h2 className="text-sm font-semibold text-zinc-900 dark:text-zinc-50">Backlog</h2>
        </div>
        <span className="text-xs text-zinc-500">
          {tickets.length} tickets · {totalPoints} pts
        </span>
      </header>
      <ul className="flex-1 space-y-3 overflow-y-auto p-4">
        {tickets.map((ticket) => (
          <TicketCard key={ticket.id} ticket={ticket} />
        ))}
      </ul>
    </section>
  );
}

"use client";

import { useState } from "react";
import { AlertCircle, Loader2, Sparkles, ImageIcon } from "lucide-react";
import { generateAsset, ApiError } from "../lib/api";
import type { VisualAssetPrompt } from "../lib/types";

type AssetState =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "done"; imageUrl: string };

function MoodboardCard({ asset }: { asset: VisualAssetPrompt }) {
  const [state, setState] = useState<AssetState>({ status: "idle" });

  async function handleGenerate() {
    setState({ status: "loading" });
    try {
      const { imageUrl } = await generateAsset(asset.falPrompt);
      setState({ status: "done", imageUrl });
    } catch (err) {
      setState({
        status: "error",
        message: err instanceof ApiError ? err.message : "Image generation failed.",
      });
    }
  }

  return (
    <li className="overflow-hidden rounded-xl border border-zinc-200 bg-white dark:border-zinc-800 dark:bg-zinc-950">
      <div className="flex aspect-video items-center justify-center bg-zinc-100 dark:bg-zinc-900">
        {state.status === "done" ? (
          // Generated image URLs come from Fal.ai's own dynamic media host —
          // plain <img> avoids configuring next.config.ts image domains for a demo.
          // eslint-disable-next-line @next/next/no-img-element
          <img src={state.imageUrl} alt={asset.assetName} className="size-full object-cover" />
        ) : state.status === "loading" ? (
          <Loader2 className="size-6 animate-spin text-violet-500" />
        ) : (
          <ImageIcon className="size-6 text-zinc-300 dark:text-zinc-700" />
        )}
      </div>

      <div className="p-4">
        <h3 className="font-medium text-zinc-900 dark:text-zinc-50">{asset.assetName}</h3>
        <p className="mt-1 line-clamp-3 text-xs text-zinc-500 dark:text-zinc-400">{asset.falPrompt}</p>

        {state.status === "error" && (
          <p className="mt-2 flex items-start gap-1.5 text-xs text-red-600 dark:text-red-400">
            <AlertCircle className="mt-0.5 size-3.5 shrink-0" />
            {state.message}
          </p>
        )}

        <button
          type="button"
          onClick={handleGenerate}
          disabled={state.status === "loading"}
          className="mt-3 flex w-full items-center justify-center gap-1.5 rounded-lg bg-zinc-900 px-3 py-2 text-xs font-semibold text-zinc-50 transition-colors hover:bg-zinc-700 disabled:opacity-50 dark:bg-zinc-50 dark:text-zinc-900 dark:hover:bg-zinc-200"
        >
          <Sparkles className="size-3.5" />
          {state.status === "loading"
            ? "Generating…"
            : state.status === "done"
              ? "Regenerate"
              : "Generate image"}
        </button>
      </div>
    </li>
  );
}

export function MoodboardPanel({ visualAssets }: { visualAssets: VisualAssetPrompt[] }) {
  return (
    <section className="flex h-full flex-col rounded-2xl border border-zinc-200 bg-zinc-50/60 dark:border-zinc-800 dark:bg-zinc-900/40">
      <header className="flex items-center justify-between border-b border-zinc-200 px-4 py-3 dark:border-zinc-800">
        <div className="flex items-center gap-2">
          <ImageIcon className="size-4 text-violet-600 dark:text-violet-400" />
          <h2 className="text-sm font-semibold text-zinc-900 dark:text-zinc-50">Moodboards</h2>
        </div>
        <span className="text-xs text-zinc-500">{visualAssets.length} prompts</span>
      </header>
      <ul className="flex-1 space-y-3 overflow-y-auto p-4">
        {visualAssets.map((asset) => (
          <MoodboardCard key={asset.assetName} asset={asset} />
        ))}
      </ul>
    </section>
  );
}

"use client";

import { useState } from "react";
import { AlertCircle, ArrowDownRight, ArrowUpRight, Minus, RefreshCw } from "lucide-react";
import { clsx } from "clsx";
import { ApiError, fetchDataInsights } from "../lib/api";
import type { CalaDataInsight, InsightTrend } from "../lib/types";

const TREND_META: Record<InsightTrend, { Icon: typeof ArrowUpRight; className: string }> = {
  up: { Icon: ArrowUpRight, className: "text-emerald-600 dark:text-emerald-400" },
  down: { Icon: ArrowDownRight, className: "text-red-600 dark:text-red-400" },
  flat: { Icon: Minus, className: "text-zinc-400 dark:text-zinc-500" },
};

function InsightCard({ insight }: { insight: CalaDataInsight }) {
  const { Icon, className } = TREND_META[insight.trend];
  return (
    <li className="rounded-xl border border-zinc-200 bg-white p-4 dark:border-zinc-800 dark:bg-zinc-950">
      <p className="text-xs font-medium uppercase tracking-wide text-zinc-400">{insight.metricTarget}</p>
      <div className="mt-1 flex items-baseline gap-2">
        <span className="text-2xl font-semibold text-zinc-900 dark:text-zinc-50">{insight.value}</span>
        <Icon className={clsx("size-4", className)} />
      </div>
      <p className="mt-2 text-sm font-medium text-zinc-700 dark:text-zinc-300">{insight.question}</p>
      <p className="mt-1 text-xs text-zinc-500 dark:text-zinc-400">{insight.summary}</p>
    </li>
  );
}

export function InsightsPanel({
  dataInsights,
  transcript,
  onRefresh,
}: {
  dataInsights: CalaDataInsight[];
  transcript: string;
  onRefresh: (insights: CalaDataInsight[]) => void;
}) {
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleRefresh() {
    setRefreshing(true);
    setError(null);
    try {
      const { dataInsights: fresh } = await fetchDataInsights(transcript);
      onRefresh(fresh);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Failed to refresh insights.");
    } finally {
      setRefreshing(false);
    }
  }

  return (
    <section className="flex h-full flex-col rounded-2xl border border-zinc-200 bg-zinc-50/60 dark:border-zinc-800 dark:bg-zinc-900/40">
      <header className="flex items-center justify-between border-b border-zinc-200 px-4 py-3 dark:border-zinc-800">
        <h2 className="text-sm font-semibold text-zinc-900 dark:text-zinc-50">
          Data Insights <span className="font-normal text-zinc-400">· Cala</span>
        </h2>
        <button
          type="button"
          onClick={handleRefresh}
          disabled={refreshing}
          className="flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-medium text-zinc-500 transition-colors hover:bg-zinc-100 disabled:opacity-50 dark:text-zinc-400 dark:hover:bg-zinc-800"
        >
          <RefreshCw className={clsx("size-3.5", refreshing && "animate-spin")} />
          Refresh
        </button>
      </header>

      {error && (
        <p className="flex items-start gap-1.5 px-4 pt-3 text-xs text-red-600 dark:text-red-400">
          <AlertCircle className="mt-0.5 size-3.5 shrink-0" />
          {error}
        </p>
      )}

      <ul className="flex-1 space-y-3 overflow-y-auto p-4">
        {dataInsights.map((insight) => (
          <InsightCard key={insight.id} insight={insight} />
        ))}
      </ul>
    </section>
  );
}

"use client";

import { FormEvent } from "react";
import { Loader2, Sparkles, Wand2 } from "lucide-react";
import { SAMPLE_TRANSCRIPT } from "../lib/sample-transcript";

export function TranscriptForm({
  transcript,
  onTranscriptChange,
  onSubmit,
  isProcessing,
}: {
  transcript: string;
  onTranscriptChange: (value: string) => void;
  onSubmit: () => void;
  isProcessing: boolean;
}) {
  function handleSubmit(event: FormEvent) {
    event.preventDefault();
    onSubmit();
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-3">
      <textarea
        value={transcript}
        onChange={(event) => onTranscriptChange(event.target.value)}
        placeholder="Paste (or type) a raw meeting transcript…"
        rows={6}
        className="w-full resize-y rounded-xl border border-zinc-200 bg-white p-3 text-sm text-zinc-900 placeholder:text-zinc-400 focus:border-violet-500 focus:outline-none dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-50"
      />
      <div className="flex flex-wrap items-center gap-2">
        <button
          type="submit"
          disabled={isProcessing || !transcript.trim()}
          className="flex items-center gap-2 rounded-lg bg-violet-600 px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-violet-500 disabled:cursor-not-allowed disabled:opacity-50"
        >
          {isProcessing ? <Loader2 className="size-4 animate-spin" /> : <Sparkles className="size-4" />}
          {isProcessing ? "Processing meeting…" : "Process meeting"}
        </button>
        <button
          type="button"
          onClick={() => onTranscriptChange(SAMPLE_TRANSCRIPT)}
          disabled={isProcessing}
          className="flex items-center gap-2 rounded-lg border border-zinc-200 px-4 py-2 text-sm font-medium text-zinc-600 transition-colors hover:bg-zinc-100 disabled:opacity-50 dark:border-zinc-800 dark:text-zinc-400 dark:hover:bg-zinc-900"
        >
          <Wand2 className="size-4" />
          Use sample transcript
        </button>
      </div>
    </form>
  );
}

"use client";

import { useState } from "react";
import { AlertCircle, Zap } from "lucide-react";
import { TranscriptForm } from "./components/TranscriptForm";
import { BacklogPanel } from "./components/BacklogPanel";
import { MoodboardPanel } from "./components/MoodboardPanel";
import { InsightsPanel } from "./components/InsightsPanel";
import { ApiError, processMeeting } from "./lib/api";
import type { ProcessMeetingResponse } from "./lib/types";

export default function Home() {
  const [transcript, setTranscript] = useState("");
  const [result, setResult] = useState<ProcessMeetingResponse | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleProcessMeeting() {
    setIsProcessing(true);
    setError(null);
    try {
      const response = await processMeeting(transcript);
      setResult(response);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Something went wrong processing the meeting.");
    } finally {
      setIsProcessing(false);
    }
  }

  return (
    <div className="flex flex-1 flex-col bg-zinc-50 dark:bg-black">
      <main className="mx-auto flex w-full max-w-6xl flex-1 flex-col gap-6 px-6 py-10">
        <header className="flex items-center gap-2">
          <span className="flex size-8 items-center justify-center rounded-lg bg-violet-600 text-white">
            <Zap className="size-4" />
          </span>
          <div>
            <h1 className="text-lg font-semibold text-zinc-900 dark:text-zinc-50">PrismAI</h1>
            <p className="text-xs text-zinc-500 dark:text-zinc-400">
              Real-time meeting copilot — backlog, moodboards &amp; data insights, at once.
            </p>
          </div>
        </header>

        <TranscriptForm
          transcript={transcript}
          onTranscriptChange={setTranscript}
          onSubmit={handleProcessMeeting}
          isProcessing={isProcessing}
        />

        {error && (
          <div className="flex items-start gap-2 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-500/30 dark:bg-red-500/10 dark:text-red-300">
            <AlertCircle className="mt-0.5 size-4 shrink-0" />
            {error}
          </div>
        )}

        {result && (
          <>
            <p className="rounded-xl border border-violet-200 bg-violet-50 p-3 text-sm text-violet-900 dark:border-violet-500/20 dark:bg-violet-500/10 dark:text-violet-200">
              {result.summary}
            </p>

            <div className="grid flex-1 grid-cols-1 gap-4 lg:h-[70vh] lg:grid-cols-3">
              <BacklogPanel tickets={result.tickets} />
              <MoodboardPanel visualAssets={result.visualAssets} />
              <InsightsPanel
                dataInsights={result.dataInsights}
                transcript={transcript}
                onRefresh={(dataInsights) => setResult({ ...result, dataInsights })}
              />
            </div>
          </>
        )}

        {!result && !isProcessing && !error && (
          <div className="flex flex-1 flex-col items-center justify-center rounded-2xl border border-dashed border-zinc-300 p-16 text-center text-sm text-zinc-400 dark:border-zinc-800">
            Paste a meeting transcript above (or load the sample) to generate a backlog, moodboards
            and data insights simultaneously.
          </div>
        )}
      </main>
    </div>
  );
}

