const { chromium } = require("playwright");

(async () => {
  const browser = await chromium.launch({ args: ["--no-sandbox"] });
  const page = await browser.newPage({ viewport: { width: 900, height: 900 } });
  page.on("pageerror", (err) => console.log("[pageerror]", String(err)));
  page.on("console", (msg) => {
    if (msg.type() === "error") console.log("[console-error]", msg.text());
  });

  await page.goto("http://localhost:3000/auth-test", { waitUntil: "load" });
  await page.waitForSelector("text=Auth flow — manual test harness");

  await page.click('button:has-text("Register")');
  await page.waitForSelector("text=user_id:", { timeout: 10000 });

  await page.click('button:has-text("Create QR session")');
  await page.waitForSelector("text=session_id:", { timeout: 10000 });

  await page.click('button:has-text("Simulate mobile scan")');

  await page.waitForSelector("text=Access token issued", { timeout: 10000 });
  await page.screenshot({ path: "/tmp/pw-check/auth-test-final.png", fullPage: true });

  const bodyText = await page.innerText("body");
  console.log("HAS 'Access token issued':", bodyText.includes("Access token issued"));
  console.log("HAS green checks (✔) count:", (bodyText.match(/✔/g) || []).length);
  console.log("HAS red crosses (✘) count:", (bodyText.match(/✘/g) || []).length);

  await browser.close();
})().catch((err) => {
  console.error("DRIVER_FAILED:", err);
  process.exit(1);
});

const { chromium } = require("playwright");

(async () => {
  const browser = await chromium.launch({
    args: [
      "--no-sandbox",
      "--use-fake-device-for-media-stream",
      "--use-fake-ui-for-media-stream", // auto-grant the mic permission prompt
      "--use-file-for-fake-audio-capture=/tmp/test-audio.wav",
    ],
  });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 1200 },
    permissions: ["microphone"],
  });
  const page = await context.newPage();

  const netLog = [];
  page.on("requestfinished", async (req) => {
    if (req.url().includes("/api/")) {
      const res = await req.response();
      netLog.push(`${req.method()} ${req.url()} -> ${res ? res.status() : "?"}`);
    }
  });
  page.on("pageerror", (err) => console.log("[pageerror]", String(err)));
  page.on("console", (msg) => {
    if (msg.type() === "error") console.log("[console-error]", msg.text());
  });

  await page.goto("http://localhost:3000", { waitUntil: "load" });
  await page.click('button:has-text("Record audio")');
  await page.waitForSelector("text=Tap to record");

  // Start recording (mic button)
  await page.click('button[aria-label="Start recording"]');
  await page.waitForSelector('button[aria-label="Stop recording"]');
  console.log("Recording started, waiting ~9s for the fake mic clip to play through...");
  await page.waitForTimeout(9000);

  await page.screenshot({ path: "/tmp/pw-check/audio-01-recording.png" });

  await page.click('button[aria-label="Stop recording"]');
  console.log("Stopped. Waiting for pipeline to complete (SSE)...");

  const outcome = await Promise.race([
    page.waitForSelector("text=Backlog", { timeout: 60000 }).then(() => "backlog"),
    page
      .waitForSelector(".text-red-700, .text-red-300", { timeout: 60000 })
      .then(() => "error-banner"),
  ]).catch(() => "timeout");
  console.log("OUTCOME:", outcome);

  await page.waitForTimeout(3000); // let any in-flight image generations settle for the screenshot
  await page.screenshot({ path: "/tmp/pw-check/audio-02-result.png", fullPage: true });

  const bodyText = await page.innerText("body");
  console.log("HAS transcript quote:", /".+"/.test(bodyText) || bodyText.includes("“"));
  console.log("HAS Backlog:", bodyText.includes("Backlog"));
  console.log("HAS Moodboards:", bodyText.includes("Moodboards"));
  console.log("HAS Data Insights:", bodyText.includes("Data Insights"));

  console.log("\n--- network calls ---");
  console.log(netLog.join("\n"));

  await browser.close();
})().catch((err) => {
  console.error("DRIVER_FAILED:", err);
  process.exit(1);
});

